/** The hub's rows (design order) and the real plan each "seat" names. */
const ROWS = ["digitalocean", "hostinger", "godaddy", "bluehost", "namecheap", "hostgator", "cloudways", "ionos", "kamatera", "a2hosting"];
const SEAT: Record<string, { vps?: string; hosting?: string; label?: string }> = {
  digitalocean: { vps: "standard" }, hostinger: { hosting: "business" }, godaddy: { vps: "starter" },
  bluehost: { vps: "standard" }, namecheap: { vps: "starter" }, hostgator: { vps: "standard" },
  cloudways: { vps: "pro" }, ionos: { vps: "standard" }, kamatera: { vps: "pro" }, a2hosting: { label: "GAME SERVER" },
};

/** /compare — seats name real plans, destinations are real regions (rows
 *  alternate across the enabled regions, as the design alternated SGP/FSN),
 *  DigitalOcean's score is counted from its comparison table. */
export async function load(_p: Record<string, string>) {
  const [regions, promo] = await Promise.all([regionFacts(), hostingPromoActive()]);
  const code = (c: string) => `NXEON ${c.replace(/\d+$/, "").toUpperCase()}`;
  const city: Record<string, string> = {};
  for (const r of regions.regions) city[code(r.code)] = r.label;

  const slots: Record<string, string> = {};
  let first: { to: string; seat: string } | null = null;
  for (const [i, k] of ROWS.entries()) {
    const s = SEAT[k];
    let seat = s.label ?? "";
    if (s.vps) seat = `VPS ${(await vpsPlanBySlug(s.vps)).name.toUpperCase()}`;
    if (s.hosting) {
      const h = await db.hostingPlan.findFirst({ where: { slug: s.hosting, active: true } });
      if (!h) throw new Error(`nxm /compare: no active hosting plan "${s.hosting}"`);
      seat = `WEB ${h.name.toUpperCase()}`;
    }
    const to = code(regions.regions[i % regions.regions.length].code);
    slots[`hub.seat.${k}:html`] = scriptJson(seat);
    slots[`hub.to.${k}:html`] = scriptJson(to);
    slots[`hub.to.${k}`] = to;
    if (!first) first = { to, seat };
  }
  const v = doVerdicts(promo);
  slots["hub.score.digitalocean:html"] = scriptJson([v.w, v.e, v.l]);

  return {
    data: { city },
    slots: {
      ...slots,
      "pass.to": first!.to, "pass.city": city[first!.to], "pass.seat": first!.seat,
      "regions.routes": `Nxeon flies ${regions.word} route${regions.count === 1 ? "" : "s"}: ${regions.list}.`,
      "promo.final": promo
        ? "First month free on hosting plans, a free migration, and cancel anytime."
        : "A free migration, and cancel anytime.",
    },
  };
}
"""/compare (hub): the boarding pass's seat (a real plan name), destination
(a real, enabled region), DigitalOcean's win/even/lose score (counted from
the vs-DigitalOcean table itself), regions and the first-month-free line —
from the system. The rest of the hub data is the design's copy."""
import json, re
from _w import sub, resub

# Cloudways charges $99 per application for non-WordPress migrations beyond
# a plan's included quota (1 on Standard, 5 on Agency) — Cloudways' own help
# centre, "How to Request a Managed Application Migration to Cloudways"
# (support.cloudways.com/en/articles/5133547) and
# cloudways.com/en/free-website-migration-service.php, checked Sept 2026.
ALLOW = {"$99"}

def body(s):
    m = re.search(r'<script type="application/json" id="hub-data">([\s\S]*?)</script>', s)
    assert m, "hub-data not found"
    rows = json.loads(m.group(1))
    keys = [r["k"] for r in rows]
    for r in rows:
        k = r["k"]
        r["seat"] = f"@@seat.{k}@@"; r["to"] = f"@@to.{k}@@"
        if k == "digitalocean":
            assert r["s"] is not None; r["s"] = f"@@score.{k}@@"
        else:
            assert r["s"] is None, f"{k}: a score needs a real comparison table"
    out = json.dumps(rows, ensure_ascii=False)
    out = re.sub(r'"@@([\w.]+)@@"', lambda mm: "{{nxm:hub.%s:html}}" % mm.group(1), out)
    s = s[:m.start(1)] + out + s[m.end(1):]
    # the board's destination column, per row
    for k in keys:
        s = resub(s, rf'(data-k="{k}"[^>]*>[\s\S]*?<span class="fl-c to" data-t=")[^"]*(")', rf"\g<1>{{{{nxm:hub.to.{k}}}}}\g<2>")
    # the pass shows the first row until the script picks one
    s = resub(s, r'<b id="ps-to">[^<]*</b><em id="ps-city">[^<]*</em>', '<b id="ps-to">{{nxm:pass.to}}</b><em id="ps-city">{{nxm:pass.city}}</em>')
    s = resub(s, r'<b id="ps-seat">[^<]*</b>', '<b id="ps-seat">{{nxm:pass.seat}}</b>')
    s = sub(s, "<small>Nxeon flies two routes: Singapore and Falkenstein, Germany.</small>", "<small>{{nxm:regions.routes}}</small>")
    s = sub(s, "<p>First month free on hosting plans, a free migration, and cancel anytime.</p>", "<p>{{nxm:promo.final}}</p>")
    return s

def js(s):
    s = resub(s, r"const CITY = \{[^}]*\}, pass", "const CITY = __NXM.city, pass")
    return s

