/**
 * The "move from X to Nxeon" migration-intent pages' own content, shared by the
 * live pages (app/(marketing)/migrate-from-<slug>/page.tsx, rendered through
 * components/marketing/MigrateFromPageLayout.tsx) and the new marketing site
 * (app/nxm/_data/migrate-from.ts). Moved here verbatim from those page files
 * so both render the same, honest copy from one place.
 *
 * `reasons` are 3-4 honest, generic "why people leave {provider}" bullets —
 * no invented stats. `provider`/`providerSlug` match the /vps-vs-<slug>
 * comparison page's competitor.
 */

export type MigrateFaq = { q: string; a: string };

export type MigrateFromPage = {
  /** Provider display name, e.g. "Hostinger". */
  provider: string;
  /** Brand slug (logo + the /vps-vs-<slug> comparison it links to). */
  providerSlug: string;
  reasons: string[];
};

export const MIGRATE_FROM: Record<string, MigrateFromPage> = {
  a2hosting: {
    provider: "A2 Hosting",
    providerSlug: "a2hosting",
    reasons: [
      "Product lineup weighted toward shared and reseller hosting, with VPS as one tier among many",
      "Add-ons like backups, a dedicated IP and premium support are common upsells rather than included by default",
      "A cPanel/WHM-centric control panel, rather than a lean, root-first dashboard",
      "Limited focus on game-server hosting or one-click app deploys",
    ],
  },
  bluehost: {
    provider: "Bluehost",
    providerSlug: "bluehost",
    reasons: [
      "Best known as a shared/WordPress hosting brand — VPS is a smaller part of the lineup",
      "Multi-tier plans with add-ons (backups, security, dedicated IP) that add up beyond the headline price",
      "Aimed mainly at beginner website owners rather than developers who want full root control",
      "No dedicated game-server hosting product",
    ],
  },
  cloudways: {
    provider: "Cloudways",
    providerSlug: "cloudways",
    reasons: [
      "A managed layer on top of other clouds (AWS, DigitalOcean and others) rather than root access to your own box",
      "No direct SSH root access on most plans — server management goes through their panel",
      "Pricing stacks a markup on top of the underlying infrastructure provider's own rates",
      "Focused on PHP/WordPress-style app hosting rather than general-purpose VPS or game servers",
    ],
  },
  digitalocean: {
    provider: "DigitalOcean",
    providerSlug: "digitalocean",
    reasons: [
      "A broad menu of individually billed cloud primitives (droplets, spaces, load balancers, managed databases) that takes real ops experience to piece together for a simple project",
      "No first-class, one-click game-server hosting — you'd assemble that yourself on a droplet",
      "Backups, monitoring extras and premium support are separate line items rather than bundled in",
      "A general-purpose global cloud footprint, not built specifically around low-latency Asia-Pacific hosting",
    ],
  },
  godaddy: {
    provider: "GoDaddy",
    providerSlug: "godaddy",
    reasons: [
      "Best known as a domain registrar and website-builder brand — VPS/dedicated is one product among a very large catalogue",
      "A wide upsell flow at checkout (security add-ons, site backups, business email) that can make the total cost unclear",
      "Introductory promotional pricing on many plans that renews at a higher standard rate",
      "Root access and developer tooling aren't the focus — most of the product line is managed or shared hosting",
    ],
  },
  hostgator: {
    provider: "HostGator",
    providerSlug: "hostgator",
    reasons: [
      "Shared-hosting heritage brand where VPS is one tier among cPanel-based shared and reseller plans",
      "Introductory promotional rates that can renew significantly higher after the first term",
      "cPanel-centric workflow rather than a lean, root-first developer dashboard",
      "No dedicated game-server hosting product",
    ],
  },
  hostinger: {
    provider: "Hostinger",
    providerSlug: "hostinger",
    reasons: [
      "A broad consumer hosting suite (shared hosting, website builder, email) where VPS is one product among many",
      "hPanel and optional add-on panels rather than a single unmanaged, root-first dashboard",
      "Plans and pricing spread across many tiers and terms, which can make comparing the real monthly cost more work",
      "Game-server hosting is a separate product line rather than built into the same VPS dashboard flow",
    ],
  },
  ionos: {
    provider: "IONOS",
    providerSlug: "ionos",
    reasons: [
      "A large, Europe-headquartered catalogue spanning domains, shared hosting, email and cloud — VPS is one tier among many",
      "Multi-year contract terms are common on their plans, which can lock in pricing longer than a month-to-month VPS",
      "Control-panel options vary by product line rather than one consistent, root-first dashboard",
      "Not built specifically around Asia-Pacific latency or one-click game-server hosting",
    ],
  },
  kamatera: {
    provider: "Kamatera",
    providerSlug: "kamatera",
    reasons: [
      "Granular, per-resource metered pricing (CPU, RAM and disk billed separately) that can make the final monthly bill harder to predict upfront",
      "A large global data-center list that's more choice than most single-project sites actually need",
      "No first-class, one-click game-server hosting — it's general-purpose cloud infrastructure",
      "Console and setup are aimed at experienced cloud users rather than a simple deploy-in-minutes flow",
    ],
  },
  namecheap: {
    provider: "Namecheap",
    providerSlug: "namecheap",
    reasons: [
      "Best known as a domain registrar — hosting, including VPS, is a smaller, secondary part of the business",
      "Shared hosting and website-builder products dominate the lineup, with VPS a smaller, separate tier",
      "Control panel and support experience vary across its different hosting product lines",
      "No dedicated game-server hosting product built into the same dashboard as VPS",
    ],
  },
};

/** Honest defaults, sourced from the real /migrate mechanics — never invented. */
export function migrateFromDefaultFaq(provider: string): MigrateFaq[] {
  return [
    {
      q: "Will my site go down during the move?",
      a: `No. The scan and the copy are strictly read-only on your ${provider} server — we only read your files and dump your databases. Nothing there is changed, stopped, or deleted, and it keeps serving traffic the whole time. Your site only cuts over when you're happy and point your DNS at Nxeon.`,
    },
    {
      q: `Do I need to give you my ${provider} account password?`,
      a: `No. We never ask for your ${provider} account or control-panel login. What we need is SSH access to the server itself, and we don't store those credentials either. Database migration doesn't need a password at all — we dump MySQL, MariaDB and PostgreSQL using root over the source's local socket.`,
    },
    {
      q: "What if something doesn't migrate cleanly?",
      a: "We're honest here: we start everything we can — files, databases, Docker Compose stacks, services — and then verify what's actually running. Anything unusual, like a hand-built systemd unit, a one-off container, or a different-CPU-architecture binary, is listed clearly so you know the exact remaining step, or our team can take it from there.",
    },
    {
      q: `Is moving from ${provider} really free?`,
      a: "Yes. Migration is free, with no per-gigabyte fee and no migration surcharge — you only pay for the Nxeon server you keep running afterward, and you can run the migration as many times as you need before you cut over.",
    },
  ];
}

