import "server-only";
import type { ComparisonData, CompareRow } from "@/components/marketing/comparisontemplate/data";
import { DIGITALOCEAN_DATA } from "@/components/marketing/comparisontemplate/digitalocean";
import { HOSTINGER_DATA } from "@/components/marketing/comparisontemplate/hostinger";
import { GODADDY_DATA } from "@/components/marketing/comparisontemplate/godaddy";
import { BLUEHOST_DATA } from "@/components/marketing/comparisontemplate/bluehost";
import { NAMECHEAP_DATA } from "@/components/marketing/comparisontemplate/namecheap";
import { HOSTGATOR_DATA } from "@/components/marketing/comparisontemplate/hostgator";
import { CLOUDWAYS_DATA } from "@/components/marketing/comparisontemplate/cloudways";
import { IONOS_DATA } from "@/components/marketing/comparisontemplate/ionos";
import { KAMATERA_DATA } from "@/components/marketing/comparisontemplate/kamatera";
import { A2HOSTING_DATA } from "@/components/marketing/comparisontemplate/a2hosting";
import { HETZNER_DATA } from "@/components/marketing/comparisontemplate/hetzner";
import { CONTABO_DATA } from "@/components/marketing/comparisontemplate/contabo";
import { VULTR_DATA } from "@/components/marketing/comparisontemplate/vultr";
import { LINODE_DATA } from "@/components/marketing/comparisontemplate/linode";
import { OVH_DATA } from "@/components/marketing/comparisontemplate/ovh";
import { AWS_LIGHTSAIL_DATA } from "@/components/marketing/comparisontemplate/aws-lightsail";
import { COMPARISONS } from "@/lib/compare-hub";
import { MIGRATE_FROM } from "@/lib/migrate-from-pages";

/**
 * Every live competitor page, for the new site's comparison template
 * (/vps-vs-*, /*-alternative), migration pages (/migrate-from-*) and the
 * compare hub's board.
 *
 * COMPETITOR FACTS ARE NOT TYPED HERE. Each competitor's rows, verdicts,
 * reasons, "choose them if" lists, FAQ and disclaimer are the live
 * comparison page's own data object (components/marketing/comparisontemplate/
 * <competitor>.ts — the file the live page renders), imported, never copied.
 * The only competitor figures with numbers are DigitalOcean's, in ONE sourced
 * constant (DIGITALOCEAN in ./vps-vs-digitalocean.ts).
 *
 * What is added here is presentation only: the brand tint (the design
 * package's colour for the ten it designed, the brand's Simple Icons hex for
 * the rest — the same package the live CompetitorLogo uses), a short name for
 * verdict labels, and the board's short labels (from the live /compare hub's
 * own `edge` one-liner, lib/compare-hub.ts).
 */
export type Competitor = {
  key: string;
  /** production route of the comparison page */
  route: string;
  data: ComparisonData;
  /** name in "<short> wins" labels */
  short: string;
  /** brand tint (--tc) */
  color: string;
  /** the board's 12-character FROM column */
  board: string;
  /** the board's 16-character YOU GAIN column (from the live hub's `edge`) */
  gain: string;
  /** one-word kind for the boarding pass (paraphrases the live `kind`) */
  type: string;
};

const vs = (key: string, data: ComparisonData, color: string, o: Partial<Competitor> = {}): Competitor => ({
  key, route: `/vps-vs-${key}`, data, short: data.competitor.name, color,
  board: data.competitor.name.toUpperCase(), gain: "", type: "", ...o,
});
const alt = (key: string, data: ComparisonData, color: string, o: Partial<Competitor>) => vs(key, data, color, { route: `/${key}-alternative`, ...o });

// Board labels (gain/type) for the design's ten live in the design's own hub
// data (compare.gen.ts); the six below are the hub rows the design lacked.
export const COMPETITORS: Competitor[] = [
  vs("digitalocean", DIGITALOCEAN_DATA, "#0080FF"),
  vs("hostinger", HOSTINGER_DATA, "#673DE6"),
  vs("godaddy", GODADDY_DATA, "#1BB9B9"),
  vs("bluehost", BLUEHOST_DATA, "#3575D3"),
  vs("namecheap", NAMECHEAP_DATA, "#E8532C"),
  vs("hostgator", HOSTGATOR_DATA, "#F5B800"),
  vs("cloudways", CLOUDWAYS_DATA, "#4D5DF5"),
  vs("ionos", IONOS_DATA, "#1A6FFF"),
  vs("kamatera", KAMATERA_DATA, "#2E8BD8"),
  vs("a2hosting", A2HOSTING_DATA, "#5FB548", { short: "A2" }),
  // Simple Icons hex: Hetzner D50C2D, Contabo 00AAEB, Vultr 007BFC, Akamai
  // 0096D6 (Linode is Akamai's), Amazon FF9900; OVH's 123F6D is lifted halfway
  // to white so the tint reads on the navy page.
  alt("hetzner", HETZNER_DATA, "#D50C2D", { gain: "MANAGED EXTRAS", type: "EU/US infrastructure" }),
  alt("contabo", CONTABO_DATA, "#00AAEB", { gain: "ONE-CLICK APPS", type: "Big-spec VPS" }),
  alt("vultr", VULTR_DATA, "#007BFC", { gain: "NO EGRESS BILLS", type: "Self-service cloud" }),
  alt("linode", LINODE_DATA, "#0096D6", { short: "Linode", board: "LINODE", gain: "ALL-IN PRICING", type: "Developer cloud" }),
  alt("ovh", OVH_DATA, "#889FB6", { gain: "NO CARD NEEDED", type: "EU cloud, bare metal" }),
  alt("aws-lightsail", AWS_LIGHTSAIL_DATA, "#FF9900", { short: "Lightsail", board: "LIGHTSAIL", gain: "NO AWS ACCOUNT", type: "AWS on-ramp" }),
];

export const competitor = (key: string) => COMPETITORS.find((c) => c.key === key);

/** The live hub's one-liners for a competitor (lib/compare-hub.ts). */
export function hubEntry(c: Competitor) {
  const e = COMPARISONS.find((x) => x.href === c.route);
  if (!e) throw new Error(`nxm: ${c.route} is not on the live /compare hub`);
  return e;
}

/** The live /migrate-from-<key> page for a competitor, when there is one. */
export const migrateRoute = (c: Competitor) => (MIGRATE_FROM[c.key] ? `/migrate-from-${c.key}` : null);

// ── The copy's Nxeon-side facts, checked against the system ────────────────
/**
 * The live comparison copy states Nxeon's regions in prose ("two real regions
 * — Singapore and Falkenstein, Germany"). Those sentences are the live
 * pages' own and aren't rewritten; instead every render checks the system
 * still matches them and refuses to render (fail closed) if it doesn't, so a
 * page can never claim a region customers can't deploy into, or miss one.
 */
export const COPY_REGIONS = { labels: ["Germany", "Singapore"], codes: ["fsn1"] };
export function assertCopyRegions(regions: { regions: { code: string }[]; labels: string[] }) {
  const labels = [...regions.labels].sort();
  const ok = labels.join("|") === COPY_REGIONS.labels.join("|") && COPY_REGIONS.codes.every((c) => regions.regions.some((r) => r.code === c));
  if (!ok) throw new Error(`nxm comparisons: the live comparison copy describes ${COPY_REGIONS.labels.join(" + ")} (Falkenstein); enabled regions are ${labels.join(" + ")} — update the copy`);
}

export type Row = { feature: string; me: string; them: string; v: "w" | "e" | "l"; why: string };
export type Group = { label: string; rows: Row[] };
const V = { win: "w", tie: "e", other: "l" } as const;

/**
 * Per-competitor corrections to the live copy: [old, new] pairs, each asserted
 * to exist (a changed live sentence fails closed rather than silently keeping
 * a stale claim). Only where the live copy disagrees with a sourced figure or
 * with what checkout grants.
 */
type Fix = [string, string];
function fixes(c: Competitor, promo: boolean): Fix[] {
  if (c.key !== "digitalocean") return [];
  return [
    // DigitalOcean's backup rates are 20% weekly / 30% daily (DIGITALOCEAN's
    // source); the live copy's "~20%" understated the daily rate the price
    // sections use.
    ["Optional, ~20% add-on", "Optional, 20% weekly or 30% daily"],
    ["DigitalOcean bills Droplet backups at roughly 20% on top of the Droplet.", "DigitalOcean bills Droplet backups at 20% (weekly) or 30% (daily) on top of the Droplet."],
    ["Backups are included, not a 20% line item.", "Backups are included, not a 20–30% line item."],
    // first month free is a shared-hosting offer, and only while it's on
    ["which lets us keep entry pricing low and include backups and the first month free.",
      `which lets us keep entry pricing low and include backups${promo ? ", plus the first month free on shared hosting" : ""}.`],
  ];
}

function applyFixes(d: ComparisonData, list: Fix[]): ComparisonData {
  let json = JSON.stringify(d);
  for (const [a, b] of list) {
    const ja = JSON.stringify(a).slice(1, -1), jb = JSON.stringify(b).slice(1, -1);
    if (!json.includes(ja)) throw new Error(`nxm comparisons: live copy changed, "${a}" not found — review the correction`);
    json = json.split(ja).join(jb);
  }
  return JSON.parse(json);
}

/** The competitor's data as the page shows it: corrections applied, and the
 *  first-month-free row only while checkout grants it (hosting only). */
export function pageData(c: Competitor, promo: boolean): { data: ComparisonData; groups: Group[] } {
  const data = applyFixes(c.data, fixes(c, promo));
  const keep = (r: CompareRow) => promo || !/^first month free$/i.test(r.feature);
  const groups = data.compareGroups
    .map((g) => ({ label: g.label, rows: g.rows.filter(keep).map((r) => ({ feature: r.feature, me: r.nxeon, them: r.other, v: V[r.verdict], why: r.note })) }))
    .filter((g) => g.rows.length);
  return { data, groups };
}

/** Win / even / lose, counted from the rows the page shows. */
export function score(groups: Group[]) {
  const n = { w: 0, e: 0, l: 0 };
  for (const g of groups) for (const r of g.rows) n[r.v]++;
  return n;
}

