import "server-only";
import { notFound } from "next/navigation";
import { esc, nxmHref, productLd, usd, vpsPlans } from "./lib";
import { andList, annualMonthlyCents, cap, hostingPromoActive, regionFacts, scriptJson, vpsPlanBySlug } from "./products-common";
import { REGION_COUNTRY } from "@/lib/node-regions";
import { SEO } from "../_seo/registry";
import { assertCopyRegions, competitor, migrateRoute, pageData, score, type Competitor, type Group } from "./vs-competitors";
import { DO_DESIGN, DO_QUIZ, DO_SECTIONS, DO_TICKS } from "./vps-vs-digitalocean.gen";

/**
 * The comparison template (design package source/pages/_cmp), fanned out to
 * every live competitor page: /vps-vs-<x> and /<x>-alternative
 * (tools/nxm/routes/vps-vs-digitalocean.json, param `c`).
 *
 * Competitor side = the live page's own data (./vs-competitors.ts).
 * Nxeon side = the system at request time: VPS plans and prices, the annual
 * rate, enabled regions (checked against the copy), the hosting-only promo.
 */

/**
 * DigitalOcean's side — competitor data, NOT ours, and the only competitor
 * with prices. Public prices from https://www.digitalocean.com/pricing/droplets
 * (Basic Droplets, Regular SSD, monthly) and its backup rates (weekly 20% /
 * daily 30% of the Droplet price), as given in the design package
 * (source/build_compare.py, "checked September 2026" — the date the page's
 * source line states). Each is DigitalOcean's closest Droplet to the Nxeon
 * plan named by slug.
 */
export const DIGITALOCEAN = {
  checked: "September 2026",
  source: "digitalocean.com",
  dailyBackupRate: 0.3,
  weeklyBackupRate: 0.2,
  match: [
    { slug: "starter", cpu: 1, ram: 2, disk: 50, bw: 2, price: 12 },
    { slug: "standard", cpu: 2, ram: 4, disk: 80, bw: 4, price: 24 },
    { slug: "pro", cpu: 4, ram: 8, disk: 160, bw: 5, price: 48 },
  ],
};
/** Competitors with sourced prices (the template's price sections render only for these). */
const PRICED: Record<string, typeof DIGITALOCEAN> = { digitalocean: DIGITALOCEAN };

const gb = (mb: number) => Math.round((mb / 1024) * 10) / 10;
const d2 = (x: number) => usd(Math.round(x * 100));
const v3 = (x: number) => x.toFixed(3);
const pct = (r: number) => `${Math.round(r * 100)}%`;
const I = (n: string, grad = false) => `<span data-au-icon="${n}"${grad ? " data-grad" : ""}></span>`;

/** Fill the generated sections' [[X]] tokens; any left over is a bug. */
function tpl(s: string, vars: Record<string, string>) {
  const out = s.replace(/\[\[([A-Z_]+)\]\]/g, (m, k: string) => (k in vars ? vars[k] : m));
  const left = out.match(/\[\[[A-Z_]+\]\]/g);
  if (left) throw new Error(`nxm comparison: unfilled ${left.join(", ")}`);
  return out;
}

/** What the competitor's closest plan has more of — derived from both spec
 *  sheets so it can never go stale. */
