    // ── every other competitor: no competitor prices exist, so no price sections
    save = `<div class="au-glass vx-save"><small>Nxeon VPS from</small><b class="big">${from}</b><p>a month, all-in, with a dedicated IPv4 on every plan. The price you see is the price checkout charges.</p>${rv}</div>`;
