    const rows = groups.flatMap((g) => g.rows);
    const pick = [...rows.filter((r) => r.v === "w"), ...rows.filter((r) => r.v === "e")].slice(0, 4);
    if (!pick.some((r) => /migrat/i.test(r.feature))) pick.splice(3, 1, { feature: "Free migration", me: `off ${T}, done for you`, them: "", v: "w", why: "" });
    ticks = pick.map((r) => `<li>${I(tickIcon(r.feature), true)}<span><b>${esc(r.feature)}:</b> ${esc(r.me)}</span></li>`).join("");
