    quiz = [...data.chooseNxeon.slice(0, 3).map((q) => ["3,0", q]), ...data.chooseOther.slice(0, 2).map((q) => ["0,3", q])]
      .map(([w, q]) => `<div class="fq" data-w="${w}"><span>${esc(q)}</span>${seg(q, 0)}</div>`).join("");
  }

  const icon = { shield: "shield", backup: "backup", support: "users", bolt: "bolt" } as const;
  const li = (xs: string[]) => xs.map((x) => `<li>${esc(x)}</li>`).join("");
  const route = c.route;
