    trail: [{ name: SEO["/compare"].crumb, path: "/compare" }, { name: SEO[route].crumb, path: route }],
    jsonLd: [productLd("Nxeon Cloud VPS",
      `NVMe cloud VPS with full root access, a dedicated IPv4, daily backups and DDoS protection — compared honestly with ${T}.`,
      route, plans.map((x) => ({ name: `${x.n} VPS`, price: x.i ?? x.p })))],
    data: { fit },
    slots: {
      "cmp.tc": c.color,
      "cmp.t": T, "cmp.short": short, "cmp.ttag": ttag,
      "cmp.h1a": data.hero.lead.trim(), "cmp.h1b": data.hero.highlight, "cmp.sub": data.hero.body,
      "cmp.ticks:html": ticks, "cmp.save:html": save,
      "cmp.cta1": cta1.t, "cmp.cta1.href": cta1.h, "cmp.cta2": cta2.t, "cmp.cta2.href": cta2.h,
      "cmp.priced:html": pricedHtml, "cmp.am:html": amHtml,
      "cmp.rows:html": rowsHtml(groups, short), "cmp.menote": menote, "cmp.themnote": themnote,
      "cmp.rs:html": data.switchReasons.map((r) => `<article class="au-card au-hov"><span class="au-tile">${I(icon[r.icon])}</span><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p></article>`).join(""),
      "cmp.mig": mig,
      "cmp.quiz:html": quiz,
      "cmp.meif:html": li(data.chooseNxeon), "cmp.themif:html": li(data.chooseOther),
      "cmp.faq:html": data.faq.map((f, k) => `<details${k === 0 ? " open" : ""}><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join(""),
      "cmp.tm": data.disclaimer,
