import "server-only";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, nxmHref } from "./lib";
import { hostingPromoActive, regionFacts, scriptJson, vpsPlanBySlug } from "./products-common";
import { COMPETITORS, hubEntry, pageData, score } from "./vs-competitors";
import { HUB_DESIGN } from "./compare.gen";
import { db } from "@/lib/db";

/** The real plan each row's boarding-pass "seat" names (the design's picks
 *  for its ten rows; the six it lacked alternate the VPS plans). */
const SEAT: Record<string, { vps?: string; hosting?: string; label?: string }> = {
  digitalocean: { vps: "standard" }, hostinger: { hosting: "business" }, godaddy: { vps: "starter" },
  bluehost: { vps: "standard" }, namecheap: { vps: "starter" }, hostgator: { vps: "standard" },
  cloudways: { vps: "pro" }, ionos: { vps: "standard" }, kamatera: { vps: "pro" }, a2hosting: { label: "GAME SERVER" },
  hetzner: { vps: "standard" }, contabo: { vps: "pro" }, vultr: { vps: "starter" },
  linode: { vps: "standard" }, ovh: { vps: "starter" }, "aws-lightsail": { vps: "standard" },
};

/** /compare — the board lists every live comparison page (./vs-competitors),
 *  each row's score counted from its own table, destinations alternate over
 *  the enabled regions, seats name real plans. */
export async function load(_p: Record<string, string>) {
  const [regions, promo] = await Promise.all([regionFacts(), hostingPromoActive()]);
  const code = (c: string) => `NXEON ${c.replace(/\d+$/, "").toUpperCase()}`;
  const city: Record<string, string> = {};
  for (const r of regions.regions) city[code(r.code)] = r.label;

  const rows = [];
  for (const [i, c] of COMPETITORS.entries()) {
    const design = HUB_DESIGN.find((d) => d.k === c.key);
    const live = hubEntry(c);
    const s = SEAT[c.key];
    if (!s) throw new Error(`nxm /compare: no seat for ${c.key}`);
    let seat = s.label ?? "";
    if (s.vps) seat = `VPS ${(await vpsPlanBySlug(s.vps)).name.toUpperCase()}`;
    if (s.hosting) {
      const h = await db.hostingPlan.findFirst({ where: { slug: s.hosting, active: true } });
      if (!h) throw new Error(`nxm /compare: no active hosting plan "${s.hosting}"`);
      seat = `WEB ${h.name.toUpperCase()}`;
    }
    const n = score(pageData(c, promo).groups);
    rows.push({
      k: c.key,
      n: design?.n ?? live.competitor,
      board: c.board,
      c: design?.c ?? c.color,
      t: design?.t ?? c.type,
      // the pass line: the design's for its rows, else the live hub's own one-liner
      p: design?.p ?? `${live.edge.replace(/\s+—\s+/g, ", ")}.`,
      gain: design?.gain ?? c.gain,
      u: nxmHref(c.route),
      s: [n.w, n.e, n.l],
      to: code(regions.regions[i % regions.regions.length].code),
      seat,
      title: live.title,
    });
  }
  for (const d of HUB_DESIGN) if (!COMPETITORS.some((c) => c.key === d.k)) throw new Error(`nxm /compare: design row ${d.k} has no live comparison page`);
  // the design's Cloudways line quotes Cloudways' $99 per-app migration fee
  // (sourced in tools/nxm/wire/compare.py); refuse a changed figure
  for (const r of rows) if (/\$\d/.test(r.p) && !(r.k === "cloudways" && r.p.includes("$99 per site"))) throw new Error(`nxm /compare: unsourced price in ${r.k}`);

  const rowHtml = rows.map((r, i) =>
    `<button type="button" class="fl-r" data-k="${esc(r.k)}" style="--bc:${esc(r.c)}" aria-label="${esc(`${r.n} to Nxeon: ${r.p}`)}">`
    + `<span class="fl-c t" data-t="00:47"></span><span class="fl-c f" data-t="${esc(r.board)}"></span><span class="fl-c to" data-t="${esc(r.to)}"></span>`
    + `<span class="fl-c g" data-t="${esc(r.gain)}"></span><span class="fl-st ${i === 0 ? "b" : "o"}">${i === 0 ? "BOARDING" : "ON TIME"}</span></button>`).join("");
  const first = rows[0];

  return {
    data: { city },
    // every comparison page, as an ItemList (the live hub has none)
    jsonLd: [{
      "@context": "https://schema.org", "@type": "ItemList", name: "Nxeon comparisons",
      itemListElement: rows.map((r, i) => ({ "@type": "ListItem", position: i + 1, name: r.title, url: APP_URL + COMPETITORS[i].route })),
    }],
    slots: {
      "hub.rows:html": rowHtml,
      "hub.data:html": scriptJson(rows.map(({ k, n, c, t, p, u, s, gain, to, seat }) => ({ k, n, c, t, p, u, s, gain, to, seat }))),
      "pass.from": first.n.toUpperCase(), "pass.ftype": first.t,
      "pass.to": first.to, "pass.city": city[first.to], "pass.seat": first.seat,
      "regions.routes": `Nxeon flies ${regions.word} route${regions.count === 1 ? "" : "s"}: ${regions.list}.`,
      "promo.final": promo
        ? "First month free on hosting plans, a free migration, and cancel anytime."
        : "A free migration, and cancel anytime.",
    },
  };
}

