import "server-only";
import { notFound } from "next/navigation";
import { btn } from "./cards";
import { esc, introSpan, nxmHref, productLd, usd, vpsPlans } from "./lib";
import { annualMonthlyCents, regionFacts } from "./products-common";
import { annualDiscountPct } from "@/lib/annual-discount";
import { REGION_COUNTRY } from "@/lib/node-regions";
import { MIGRATE_FROM, migrateFromDefaultFaq } from "@/lib/migrate-from-pages";
import { APP_URL } from "@/components/marketing/StructuredData";
import { SEO } from "../_seo/registry";
import { competitor } from "./vs-competitors";

/**
 * /migrate-from-<host> — the design's /migrate page told for one host
 * (tools/nxm/wire/migrate_from.py explains the template choice). Host copy
 * is the live page's own (lib/migrate-from-pages.ts); plans, prices, the
 * annual rate and the demo's region come from the system.
 */
const page = (p: Record<string, string>) => MIGRATE_FROM[p.host];

export async function meta(p: Record<string, string>) {
  const m = page(p);
  if (!m) notFound();
  if (!SEO[`/migrate-from-${p.host}`]) throw new Error(`nxm SEO: no registry entry for /migrate-from-${p.host}`);
  return { type: "article" as const };
}

export async function load(p: Record<string, string>) {
  const m = page(p);
  if (!m) notFound();
  const route = `/migrate-from-${p.host}`;
  const T = m.provider;
  const [plans, annualPct, regions] = await Promise.all([vpsPlans(), annualDiscountPct(), regionFacts()]);
  if (!plans.length) throw new Error("nxm migrate-from: no active VPS plans");
  const sg = regions.regions.find((r) => REGION_COUNTRY[r.code] === "sg") ?? regions.regions[0];
  const demoHost = `nxeon-${REGION_COUNTRY[sg.code] ?? sg.code}-01`;
  const cmp = competitor(m.providerSlug);
  if (!cmp) throw new Error(`nxm migrate-from: no comparison page for ${m.providerSlug}`);

  // real plans, laid out on the page's 12-column grid (3 or 2 per row)
  const n = plans.length;
  const width = (i: number) => (n % 3 === 0 ? "w4" : n % 3 === 2 ? (i >= n - 2 ? "w6" : "w4") : (n >= 4 && i >= n - 4 ? "w6" : "w4"));
  const cards = await Promise.all(plans.map(async (x, i) => {
    const annual = await annualMonthlyCents(Math.round(x.p * 100));
    const price = x.i != null
      ? `${usd(Math.round(x.i * 100))}/mo for the ${introSpan(x.it)}, then ${usd(Math.round(x.p * 100))}/mo`
      : `${usd(Math.round(x.p * 100))}/mo`;
    return `<article class="au-card au-hov ${width(i)}"><span class="au-tile"><span data-au-icon="server"></span></span><h3>${esc(x.n)} · ${price}</h3>`
      + `<p>${x.cpu} vCPU, ${x.ram} GB RAM, ${x.disk} GB NVMe, ${x.bw} TB transfer. ${annualPct > 0 ? `${usd(annual)}/mo on an annual term.` : ""}</p>`
      + `<div style="margin-top:18px">${btn(false, x.href, `Deploy ${x.n}`)}</div></article>`;
  }));

  const faq = migrateFromDefaultFaq(T);
  const others = Object.entries(MIGRATE_FROM).filter(([k]) => k !== p.host);
  const steps = [
    ["Connect", `Point us at your ${T} server with its SSH details. No agent to install.`],
    ["Scan and detect", "A read-only scan finds files, databases, containers and apps, with sizes."],
    ["One click", "Prerequisites installed, files copied to the same paths, services brought up."],
    ["Live on Nxeon", "We verify what’s running and list anything that needs a manual touch."],
  ];

  return {
    trail: [{ name: SEO["/migrate"].crumb, path: "/migrate" }, { name: SEO[route].crumb, path: route }],
    data: { demoHost },
    jsonLd: [
      productLd("Nxeon Cloud VPS", `NVMe cloud VPS with full root access and a dedicated IPv4 — with a free migration off ${T}.`,
        route, plans.map((x) => ({ name: `${x.n} VPS`, price: x.i ?? x.p }))),
      {
        "@context": "https://schema.org", "@type": "HowTo", name: `How to move from ${T} to Nxeon`,
        description: `Nxeon's free migration: a read-only scan of your ${T} server, then files, databases and containers brought up on Nxeon.`,
        totalTime: "PT15M", estimatedCost: { "@type": "MonetaryAmount", currency: "USD", value: "0" },
        step: steps.map(([name, text], i) => ({ "@type": "HowToStep", position: i + 1, name, text, url: `${APP_URL}${route}#how` })),
      },
    ],
    slots: {
      "mf.t": T,
      "mf.sub": `Already on ${T}? Point us at it and we'll scan it, detect your whole stack, and bring it up running on Nxeon — same paths, no downtime on your ${T} server, and it's free.`,
      "mf.cmp.href": nxmHref(cmp.route),
      "mf.reasons:html": m.reasons.map((r) => `<li class="fl"><span class="w">!</span>${esc(r)}</li>`).join(""),
      "mf.plans.lede": `The price you see is the price checkout charges, read live from our catalogue. Every tier gets the same platform, root access and protection; you only choose the horsepower.${annualPct > 0 ? ` Save ${annualPct}% on an annual term.` : ""}`,
      "mf.plans:html": cards.join(""),
      "mf.hosts:html": others.map(([k, o]) => `<a href="${esc(nxmHref(`/migrate-from-${k}`))}">${esc(o.provider)}</a>`).join(""),
      "mf.faq:html": faq.map((f, i) => `<details${i === 0 ? " open" : ""}><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join(""),
      "mf.final": `Migration off ${T} is free and your old server keeps running the whole time. Connect it, scan it, and see your whole stack come up on Nxeon.`,
      "demo.host": demoHost,
    },
  };
}

