 *  game's vanilla memory need in the "Will it fit?" meter. Shown only for
 *  games with NxLabs mods. The vanilla baseline itself is the system's curve. */
const PACK: Record<string, [number, string]> = { vanilla: [1, "Vanilla"], light: [1.25, "Light mods"], modpack: [1.75, "Modpack"], heavy: [2.5, "Heavy pack"] };

