import "server-only";
import fs from "node:fs";
import path from "node:path";
import * as simpleIcons from "simple-icons";
import { esc } from "./lib";

/**
 * Competitor marks for the comparison pages and the /compare board —
 * nominative use only (identifying the competitor), never modified beyond
 * sizing and a single light ink on the dark page.
 *
 * Resolution order:
 *   1. an official file in public/nxm/logos/competitors/<key>.(svg|png),
 *      used ONLY if it has an entry in FILES below saying where it came from;
 *   2. the brand's Simple Icons glyph (the `simple-icons` package the live
 *      CompetitorLogo and the design's _logos.json use), in light ink;
 *   3. nothing — the name alone (never a guessed or drawn logo).
 */

/** Simple Icons export per competitor key. Linode: linode.com itself now
 *  shows the Akamai logo (checked 2026-09-27), so its mark is Akamai's. */
const SI: Record<string, string> = {
  digitalocean: "siDigitalocean", hostinger: "siHostinger", godaddy: "siGodaddy", namecheap: "siNamecheap",
  cloudways: "siCloudways", ionos: "siIonos", hetzner: "siHetzner", contabo: "siContabo", vultr: "siVultr",
  linode: "siAkamai", ovh: "siOvh", "aws-lightsail": "siAmazonwebservices", bisecthosting: "siBisecthosting",
};

/** Official files downloaded from the competitor's own site — source URL and
 *  date for each. A file without an entry here is ignored. */
export const FILES: Record<string, { file: string; source: string; checked: string }> = {};

type Icon = { title: string; path: string };
const LOGO_DIR = path.join(process.cwd(), "public", "nxm", "logos", "competitors");

/** The mark for a competitor, `px` tall, or "" when none is on file. */
export function logoHtml(key: string, name: string, px: number, cls = "vs-logo") {
  const f = FILES[key];
  if (f && fs.existsSync(path.join(LOGO_DIR, f.file))) {
    return `<img class="${cls}" src="/nxm/logos/competitors/${esc(f.file)}" alt="${esc(name)} logo" height="${px}" style="height:${px}px;width:auto" loading="lazy" decoding="async">`;
  }
  const icon = SI[key] ? ((simpleIcons as unknown as Record<string, Icon | undefined>)[SI[key]]) : undefined;
  if (icon) {
    return `<svg class="${cls}" role="img" aria-label="${esc(name)} logo" viewBox="0 0 24 24" width="${px}" height="${px}" fill="currentColor"><path d="${icon.path}"/></svg>`;
  }
  return "";
}

