/* ============ Compare hub: split-flap board + boarding pass ============ */
(function terminal() {
  const D = JSON.parse($('#hub-data').textContent), rows = $$('.fl-r'), CS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const W = { t: 5, f: 12, to: 9, g: 16 };
  rows.forEach(r => $$('.fl-c', r).forEach(c => { const key = [...c.classList].find(x => W[x]); const txt = c.dataset.t.slice(0, W[key]).padEnd(W[key], ' ');
    c.innerHTML = [...txt].map(ch => `<span class="ch" data-c="${ch}">${ch === ' ' ? '' : ch}</span>`).join(''); }));
  let flapped = false;
  function flap() { if (flapped || RM) return; flapped = true;
    rows.forEach((r, ri) => $$('.ch', r).forEach((ch, ci) => { const fin = ch.dataset.c; if (fin === ' ') return; let n = 6 + Math.floor(Math.random() * 8) + ci % 5;
      setTimeout(function spin() { if (n-- > 0) { ch.textContent = CS[Math.floor(Math.random() * CS.length)]; ch.classList.remove('fl'); void ch.offsetWidth; ch.classList.add('fl'); setTimeout(spin, 55); } else { ch.textContent = fin; ch.classList.remove('fl'); } }, ri * 90 + ci * 12); })); }
  watch($('#board'), v => { if (v) flap(); }, { threshold: .25 });
  const clk = $('#bt-clock'); const tick = () => { const d = new Date(); clk.textContent = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); }; tick(); setInterval(tick, 15000);
  const CITY = __NXM.city, pass = $('#pass');
  function bars(seed) { let h = 0; for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0; let x = 0, out = ''; while (x < 160) { h = (h * 1103515245 + 12345) >>> 0; const w = 1 + (h >>> 16) % 4; if ((h >>> 8) % 3) out += `<rect x="${x}" y="0" width="${w}" height="46"/>`; x += w + 1; } return out; }
  function pick(k) { const d = D.find(x => x.k === k); rows.forEach(r => r.setAttribute('aria-pressed', String(r.dataset.k === k))); document.body.style.setProperty('--hc', d.c);
    $('#ps-from').textContent = d.n.toUpperCase(); $('#ps-ftype').textContent = d.t; $('#ps-to').textContent = d.to; $('#ps-city').textContent = CITY[d.to]; $('#ps-seat').textContent = d.seat; $('#ps-why').textContent = d.p; $('#ps-go').href = d.u;
    $('#ps-score').innerHTML = d.s ? `<span class="w"><b>${d.s[0]}</b>Nxeon</span><span class="e"><b>${d.s[1]}</b>Even</span><span class="l"><b>${d.s[2]}</b>${d.n}</span>` : `<span class="na">Full row-by-row verdicts inside.</span>`;
    $('#ps-bar').innerHTML = bars(d.k + d.to); pass.classList.remove('print'); void pass.offsetWidth; pass.classList.add('print'); }
  rows.forEach(r => r.addEventListener('click', () => pick(r.dataset.k))); pick(D[0].k);

4:const RM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
9:const watch = (el, cb, opts) => { if (!el) return null; const io = new IntersectionObserver(es => es.forEach(e => cb(e.isIntersecting, e)), opts); io.observe(el); return io; };

