python3 - <<'EOF'
f='tools/nxm/wire/compare.py'
s=open(f).read()
old='''def js(s):
    s = resub(s, r"const CITY = \\{[^}]*\\}, pass", "const CITY = __NXM.city, pass")'''
assert old in s
new='''# The split-flap, rebuilt for the owner (2026-09-27: "too laggy, runs too
# long"). The server renders every cell's final characters, so nothing moves
# without JS or with reduced motion. On first sight each row flips ONCE: rows
# entering the viewport together are staggered, each character shows 3-4
# random frames, and ONE requestAnimationFrame loop drives every cell (no
# per-cell timers). A flip is a Web Animation of transform + opacity (no
# class toggling, no forced reflow); cells are fixed-size and `contain`ed, so a
# character swap never relays out the board. Worst case, a full viewport of
# rows: 500ms stagger + 200ms across a row + 4-5 frames x 60ms = ~1.0s.
FLAP_OLD = r"  const W = \\{ t: 5, f: 12, to: 9, g: 16 \\};[\\s\\S]*?watch\\(\\$\\('#board'\\), v => \\{ if \\(v\\) flap\\(\\); \\}, \\{ threshold: \\.25 \\}\\);"
FLAP_NEW = """  const STEP = 60, ROW = 45, CH = 10, SPAN = 500, FLIP = [{ transform: 'rotateX(0deg)', opacity: 1 }, { transform: 'rotateX(80deg)', opacity: .55, offset: .5 }, { transform: 'rotateX(0deg)', opacity: 1 }];
  const narrow = window.matchMedia('(max-width:1080px)'), queue = []; let raf = 0;
  function frame(now) { let live = 0;
    for (const q of queue) { if (q.done) continue; live++; const k = Math.floor((now - q.at) / STEP); if (k < 0 || k === q.k) continue; q.k = k;
      if (k >= q.n) { q.el.textContent = q.fin; q.done = true; } else q.el.textContent = CS[(Math.random() * CS.length) | 0];
      q.el.animate(FLIP, { duration: STEP - 8 }); }
    if (live) raf = requestAnimationFrame(frame); else { raf = 0; queue.length = 0; } }
  const io = !RM && 'IntersectionObserver' in window && new IntersectionObserver(es => {
    const vis = es.filter(e => e.isIntersecting).map(e => e.target); if (!vis.length) return;
    const base = performance.now(), gap = Math.min(ROW, SPAN / vis.length);
    vis.forEach((r, ri) => { io.unobserve(r);
      $$('.fl-c', r).forEach(c => { if (narrow.matches && (c.classList.contains('to') || c.classList.contains('g'))) return;
        $$('.ch', c).forEach((el, ci) => { const fin = el.dataset.c; if (fin === ' ') return;
          queue.push({ el, fin, at: base + ri * gap + Math.min(ci * CH, 200), n: 3 + (ci & 1), k: -1, done: false }); }); }); });
    if (!raf && queue.length) raf = requestAnimationFrame(frame); }, { threshold: .6 });
  if (io) rows.forEach(r => io.observe(r));"""

def js(s):
    s = resub(s, FLAP_OLD, lambda m: FLAP_NEW)
    s = resub(s, r"const CITY = \\{[^}]*\\}, pass", "const CITY = __NXM.city, pass")'''
s=s.replace(old,new)
open(f,'w').write(s)
EOF
