import "server-only";
import type { ComparisonData } from "@/components/marketing/comparisontemplate/data";
import { getSettingBool, getSettingInt } from "@/lib/settings";
import { INSTALLABLE_FAMILIES } from "@/lib/mod-install-support";
import { BACKUP_FREE_KEEP } from "@/lib/backup-tiers";
import { SUPPORT_REPLY_WITHIN } from "@/lib/support-promise";
import { sections as TERMS } from "@/lib/legal/terms";
import { hostingPromoActive, regionFacts } from "./products-common";
import { usd, vpsPlans, type VpsPlan } from "./lib";
import { deployRegions, realTiers, sellableGames, type RealTier } from "./games-lib";
import { HOST_SPECS } from "./vs-hosts-data";

/**
 * Comparisons with hosts the live site has no page for (game-server hosts,
 * more VPS hosts) — owner request 2026-09-27.
 *
 * Every competitor figure lives in ONE constant per competitor
 * (./vs-hosts-data.ts), each with the competitor's own page it came from and
 * the date it was checked; nothing is shown that isn't in one. Nxeon's side is
 * read from the system on every request (this file's hostCtx): Minecraft
 * tiers / VPS plans and prices, games sold, regions, the free Minecraft
 * tier, one-click mod installs, backup retention, the support promise and the
 * refund term. Price rows are computed from both, so a verdict can never
 * disagree with the numbers beside it.
 */

export type Src = { url: string; checked: string };
export type HostCtx = {
  promo: boolean;
  regions: { labels: string[]; list: string; count: number; word: string };
  mc: RealTier[];
  vps: VpsPlan[];
  games: number;
  freeMc: boolean;
  freeMcRamGB: number;
  oneClickMc: boolean;
  backupKeep: number;
  support: string;
  nonRefundable: boolean;
};

/** Nxeon's side, from the system. */
export async function hostCtx(): Promise<HostCtx> {
  const [promo, regions, dRegions, vps, games, freeMc, freeRam] = await Promise.all([
    hostingPromoActive(), regionFacts(), deployRegions(), vpsPlans(), sellableGames(),
    getSettingBool("free_minecraft_enabled", false), getSettingInt("free_minecraft_ram_mb", 1024),
  ]);
  const mc = await realTiers("minecraft", dRegions.map((r) => r.code));
  const terms = JSON.stringify(TERMS);
  return {
    promo, regions, mc, vps, games: games.length, freeMc, freeMcRamGB: Math.round((freeRam / 1024) * 10) / 10,
    oneClickMc: INSTALLABLE_FAMILIES.has("minecraft"), backupKeep: BACKUP_FREE_KEEP,
    support: `A person replies ${SUPPORT_REPLY_WITHIN}`,
    nonRefundable: terms.includes("fees are non-refundable"),
  };
}

type Val = string | ((x: HostCtx) => string);
type Verdict = "win" | "tie" | "other";
export type HostRow = { feature: string; me: Val; them: string; v: Verdict | ((x: HostCtx) => Verdict); note: Val; src: Src | null; when?: (x: HostCtx) => boolean };
export type HostPlan = { name: string; ram: number; usd: number; intro?: number; cpu?: number; disk?: number; note?: string };

export type HostSpec = {
  key: string; name: string; short?: string; board?: string;
  cat: "game" | "cloud";
  /** brand tint (Simple Icons hex or the site's own brand colour) */
  color: string;
  /** board: YOU GAIN (≤16 chars), pass kind, pass one-liner */
  gain: string; type: string; edge: string;
  /** neutral one-liner, paraphrasing how they describe themselves (source in `site`) */
  kind: string;
  site: Src;
  hero: { lead: string; highlight: string; body: Val };
  /** their plans as listed (monthly USD), compared to Nxeon's plan of the same RAM */
  price?: { of: "minecraft" | "vps"; src: Src; plans: HostPlan[] };
  groups: { label: string; rows: HostRow[] }[];
  reasons: { icon: "shield" | "backup" | "support" | "bolt"; title: string; body: Val }[];
  chooseNxeon: Val[];
  chooseThem: string[];
  faq: { q: string; a: Val }[];
};

export const HOSTS: HostSpec[] = HOST_SPECS;

const val = (v: Val, x: HostCtx) => (typeof v === "function" ? v(x) : v);
const host = (u: string) => new URL(u).hostname.replace(/^www\./, "");

/** Nxeon's plan of the same RAM (Minecraft tier or VPS plan). */
function nxMatch(of: "minecraft" | "vps", ram: number, x: HostCtx) {
  if (of === "minecraft") {
    const t = x.mc.find((m) => m.ram === ram);
    return t && { name: t.name, p: t.p, i: t.i, is: t.is };
  }
  const p = x.vps.find((v) => v.ram === ram);
  return p && { name: p.n, p: p.p, i: p.i, is: p.it == null ? "first term" : p.it === 1 ? "first month" : `first ${p.it} months` };
}

/** Price rows: their listed plan vs Nxeon's plan of the same RAM, today. */
function priceRows(h: HostSpec, x: HostCtx) {
  if (!h.price) return [];
  const P = h.price;
  const d = (n: number) => usd(Math.round(n * 100));
  return P.plans.flatMap((pl) => {
    const nx = nxMatch(P.of, pl.ram, x);
    if (!nx) return [];
    const v: Verdict = nx.p < pl.usd * 0.97 ? "win" : nx.p > pl.usd * 1.03 ? "other" : "tie";
    const label = P.of === "minecraft" ? `Minecraft, ${pl.ram} GB RAM` : `VPS, ${pl.ram} GB RAM`;
    return [{
      feature: label,
      nxeon: `${d(nx.p)}/mo (${nx.name})${nx.i != null ? `, ${d(nx.i)} for the ${nx.is}` : ""}`,
      other: `${d(pl.usd)}/mo (${pl.name})${pl.intro != null ? `, ${d(pl.intro)} to start` : ""}`,
      verdict: v,
      note: `${h.name}'s ${pl.name} as listed on ${host(P.src.url)}, checked ${P.src.checked}${pl.note ? ` (${pl.note})` : ""}. Nxeon's ${nx.name} is what checkout charges today. Regular monthly prices compared.`,
    }];
  });
}

/** The page's ComparisonData: sourced competitor side + the system's Nxeon side. */
export function buildHostData(h: HostSpec, x: HostCtx): ComparisonData {
  const price = priceRows(h, x);
  const groups = h.groups.map((g) => ({
    label: g.label,
    rows: g.rows.filter((r) => !r.when || r.when(x)).map((r) => ({
      feature: r.feature, nxeon: val(r.me, x), other: r.them,
      verdict: typeof r.v === "function" ? r.v(x) : r.v,
      note: val(r.note, x) + (r.src ? ` Source: ${host(r.src.url)}, checked ${r.src.checked}.` : ""),
    })),
  }));
  const dates = [h.site, h.price?.src, ...h.groups.flatMap((g) => g.rows.map((r) => r.src))].filter(Boolean) as Src[];
  const checked = [...new Set(dates.map((s) => s.checked))].join(", ");
  return {
    competitor: { name: h.name, slug: h.key, kind: h.kind },
    hero: { lead: h.hero.lead, highlight: h.hero.highlight, body: val(h.hero.body, x) },
    compareGroups: [...(price.length ? [{ label: "Price, as listed", rows: price }] : []), ...groups].filter((g) => g.rows.length),
    switchReasons: h.reasons.map((r) => ({ icon: r.icon, title: r.title, body: val(r.body, x) })),
    chooseNxeon: h.chooseNxeon.map((c) => val(c, x)),
    chooseOther: h.chooseThem,
    reviews: [],
    faq: h.faq.map((f) => ({ q: f.q, a: val(f.a, x) })),
    disclaimer: `${h.name} is a trademark of its respective owner and is not affiliated with Nxeon. ${h.name}'s figures are from its own public pages (${host(h.site.url)}), checked ${checked}; Nxeon's are read live from our catalogue. Always check each provider's current plans and pricing.`,
  };
}

