import type { HostCtx, HostPlan, HostRow, HostSpec, Src } from "./vs-hosts";

/**
 * Competitor facts for the comparisons the live site has no page for — ONE
 * constant per competitor, every figure with the competitor's own page it
 * came from and the date it was checked. Researched 2026-09-27 from each
 * host's own site only (pricing, features, locations, terms/refund pages);
 * prices re-read from the raw page HTML where the page renders them with JS.
 * A fact that couldn't be found on their own site is simply absent — never
 * filled in. Nxeon's side of every row comes from the system (./vs-hosts.ts).
 *
 * Re-check these before launch and whenever a competitor changes its
 * pricing; `checked` is shown on the page next to each figure.
 */

const CHECKED = "2026-09-27";
const S = (url: string): Src => ({ url, checked: CHECKED });
const $ = (n: number) => `$${n.toFixed(2)}`;

// ── the facts ───────────────────────────────────────────────────────────────
type Fact = { text: string; src: Src };
type GameFacts = {
  key: string; name: string; short?: string; board?: string;
  color: string; gain: string; type: string; edge: string; kind: string;
  site: Src;
  /** games they say they host */ games?: { n: number; text: string; src: Src };
  /** Minecraft Java plans, monthly USD as listed */ plans?: { src: Src; plans: HostPlan[] };
  /** number of locations they list */ locations?: { n: number; text: string; src: Src };
  refund?: Fact & { days: number };
  free?: Fact;
  slots?: Fact;
  storage?: Fact & { nvme: boolean };
  backups?: Fact & { paid?: boolean };
  ddos?: Fact;
  mods?: Fact & { oneClick: boolean };
  support?: Fact & { h24: boolean };
  panel?: Fact;
  yearly?: Fact & { pct: number };
  hero: { lead: string; highlight: string; body: (x: HostCtx) => string };
  chooseThem: string[];
  extraRows?: HostRow[];
  extraFaq?: { q: string; a: string }[];
};

export const ATERNOS: GameFacts = {
  key: "aternos", name: "Aternos", color: "#2484CC", gain: "NO QUEUE", type: "Free Minecraft host",
  edge: "Paid servers that stay online, with no start-up queue",
  kind: "free Minecraft server host", site: S("https://aternos.org/"),
  games: { n: 3, text: "Minecraft Java, Minecraft Bedrock and Hytale", src: S("https://aternos.org/") },
  free: { text: "Free forever, there is no way to pay; servers queue at busy times and stop when the last player leaves", src: S("https://support.aternos.org/hc/en-us/articles/31771896948253-24-7-Hosting") },
  slots: { text: "Unlimited slots", src: S("https://aternos.org/") },
  backups: { text: "Automatic backups to your Google Drive", src: S("https://aternos.org/") },
  ddos: { text: "DDoS protected, free", src: S("https://aternos.org/") },
  mods: { text: "Mods, plugins and preconfigured modpacks", oneClick: true, src: S("https://aternos.org/") },
  support: { text: "Discord, support tickets, email", h24: false, src: S("https://support.aternos.org/hc/en-us/articles/360027235811-Contact-support") },
  hero: {
    lead: "Same Minecraft. ", highlight: "Always on, no queue.",
    body: (x) => `Aternos is genuinely free, forever, and that's hard to beat. The trade-off is a queue at busy times and a server that stops when the last player leaves. Nxeon runs paid servers that stay online around the clock${x.freeMc ? `, plus a free tier of our own` : ""}. Compared honestly, row by row, including where Aternos wins.`,
  },
  chooseThem: ["You want a server that costs nothing, ever", "You're fine with it stopping when everyone leaves", "You can wait in a queue at busy times", "You want unlimited player slots for free"],
  extraRows: [
    { feature: "Always online", me: "Paid servers run 24/7", them: "No 24/7 hosting: the server stops when the last player leaves", v: "win",
      note: "Aternos stops idle servers to stay free for everyone; a paid Nxeon server keeps running when nobody is on.", src: S("https://support.aternos.org/hc/en-us/articles/31771896948253-24-7-Hosting") },
    { feature: "Start-up queue", me: "No queue", them: "A queue when their capacity is full", v: "win",
      note: "Aternos has limited resources, so players wait in a queue when demand is high.", src: S("https://support.aternos.org/hc/en-us/articles/360026950812-Queue") },
  ],
  extraFaq: [{ q: "Is Aternos really free?", a: "Yes. Aternos says it is free and will always be free, with no way to pay for anything. The trade-offs it states itself: servers stop when the last player leaves, and there's a queue when its capacity is full." }],
};

export const SHOCKBYTE: GameFacts = {
  key: "shockbyte", name: "Shockbyte", color: "#3C84FC", gain: "ONE ACCOUNT", type: "Game server host",
  edge: "Game servers next to your VPS, websites and domains, in one account",
  kind: "game server host since 2013", site: S("https://shockbyte.com/"),
  games: { n: 60, text: "Over 60 games", src: S("https://shockbyte.com/") },
  plans: { src: S("https://shockbyte.com/games/minecraft-server-hosting"), plans: [
    { name: "Sand", ram: 2, usd: 5.59, note: "30% off recurring, list $7.99" },
    { name: "Iron", ram: 4, usd: 11.19, note: "30% off recurring, list $15.99" },
    { name: "Emerald", ram: 8, usd: 22.39, note: "30% off recurring" },
  ] },
  locations: { n: 8, text: "8: Europe, North America Central and East, India, Singapore, Japan, Australia, Brazil", src: S("https://shockbyte.com/api/locations") },
  refund: { days: 3, text: "72 hours on a new plan (not renewals)", src: S("https://shockbyte.com/legal/terms-of-service") },
  ddos: { text: "DDoS protection guaranteed under their SLA", src: S("https://shockbyte.com/") },
  backups: { text: "Backups, with a guaranteed primary backup slot", src: S("https://shockbyte.com/help/knowledgebase/articles/guaranteed-backup") },
  mods: { text: "One-click installs incl. CurseForge, FTB, Technic", oneClick: true, src: S("https://shockbyte.com/games/minecraft-server-hosting") },
  support: { text: "24/7 support team", h24: true, src: S("https://shockbyte.com/contact") },
  panel: { text: "Their own Shockbyte Control Panel", src: S("https://shockbyte.com/hardware") },
  yearly: { text: "50% off annually, 10% off quarterly", pct: 50, src: S("https://shockbyte.com/games/minecraft-server-hosting") },
  hero: {
    lead: "Same game servers. ", highlight: "One account for everything.",
    body: (x) => `Shockbyte hosts over 60 games from 8 regions with 24/7 support. Nxeon runs ${x.games} games in ${x.regions.list}, in the same account as your VPS, websites and domains. Compared honestly, row by row, including where Shockbyte wins.`,
  },
  chooseThem: ["You need a region outside ours (they list 8)", "You want 24/7 support", "You pay yearly and want their 50% annual discount", "You want a 72-hour refund window"],
