// ── how a game host's facts become a comparison ────────────────────────────
const cheapestMc = (x: HostCtx) => $(Math.min(...x.mc.map((t) => t.p)));

function gameHost(f: GameFacts): HostSpec {
  const rows: Record<string, HostRow[]> = { "Pricing and terms": [], Platform: [], "Management and support": [] };
  const P = rows["Pricing and terms"], L = rows.Platform, M = rows["Management and support"];
  if (f.free) P.push({ feature: "Free option", me: (x) => (x.freeMc ? `Free Minecraft tier: ${x.freeMcRamGB} GB, sleeps when idle` : "No free tier today"), them: f.free.text,
    v: (x) => (x.freeMc ? "tie" : "other"), note: "Both free options have limits; the paid plans are where you get a server to yourself.", src: f.free.src });
  if (f.refund) P.push({ feature: "Refunds", me: (x) => (x.nonRefundable ? "No refund window; cancel anytime" : "See our Terms"), them: f.refund.text, v: "other",
    note: `${f.name} offers a refund window; Nxeon's Terms make fees non-refundable, so check with a small plan first.`, src: f.refund.src });
  if (f.yearly) P.push({ feature: "Paying yearly", me: (x) => `${x.annualPct}% off annual`, them: f.yearly.text,
    v: (x) => (x.annualPct > f.yearly!.pct ? "win" : x.annualPct === f.yearly!.pct ? "tie" : "other"), note: "Both discount longer terms; the bigger annual discount wins this row.", src: f.yearly.src });
  if (f.games) L.push({ feature: "Games", me: (x) => `${x.games} games`, them: f.games.text,
    v: (x) => (x.games > f.games!.n ? "win" : x.games === f.games!.n ? "tie" : "other"), note: "Counted from what each of us sells today.", src: f.games.src });
  if (f.locations) L.push({ feature: "Locations", me: (x) => `${x.regions.list} (${x.regions.count})`, them: f.locations.text,
    v: (x) => (x.regions.count > f.locations!.n ? "win" : x.regions.count === f.locations!.n ? "tie" : "other"), note: `If your players are far from our regions, ${f.name}'s wider map is the better fit.`, src: f.locations.src });
  if (f.slots) L.push({ feature: "Player slots", me: (x) => (x.mcSlots ? `${x.mcSlots} slots by plan` : "By plan"), them: f.slots.text, v: "other",
    note: "Nxeon's Minecraft plans set a slot count per size.", src: f.slots.src });
  if (f.storage) L.push({ feature: "Storage", me: "NVMe", them: f.storage.text, v: f.storage.nvme ? "tie" : "win", note: "NVMe loads chunks and saves worlds faster than SATA SSD.", src: f.storage.src });
  if (f.mods) L.push({ feature: "Mods and modpacks", me: (x) => (x.oneClickMc ? "One-click mod installs from NxLabs" : "Full file access (SFTP) for mods"), them: f.mods.text,
    v: (x) => (x.oneClickMc ? "tie" : f.mods!.oneClick ? "other" : "tie"), note: "Both let you run mods; the difference is how much is automated.", src: f.mods.src });
  if (f.ddos) L.push({ feature: "DDoS protection", me: "Always-on DDoS filtering", them: f.ddos.text, v: "tie", note: "Both protect game traffic by default.", src: f.ddos.src });
  if (f.backups) M.push({ feature: "Backups", me: (x) => `Daily, last ${x.backupKeep} kept free`, them: f.backups.text, v: f.backups.paid ? "win" : "tie",
    note: f.backups.paid ? `On ${f.name} backups are an add-on you choose at checkout; on Nxeon they're on by default.` : "Both keep backups of your world.", src: f.backups.src });
  if (f.support) M.push({ feature: "Support", me: (x) => x.support, them: f.support.text, v: f.support.h24 ? "other" : "tie",
    note: f.support.h24 ? `${f.name} staffs support around the clock; Nxeon promises a reply within one business day.` : "Both answer through their own channels.", src: f.support.src });
  M.push({ feature: "Also in the same account", me: "VPS, web hosting, domains and email", them: `${f.name}'s own product line`, v: "win",
    note: "One login and one bill for your game server, your website and your domain.", src: null });
  for (const r of f.extraRows ?? []) (r.feature.includes("pricing") ? P : L).push(r);

  return {
    key: f.key, name: f.name, short: f.short, board: f.board, cat: "game", color: f.color, gain: f.gain, type: f.type, edge: f.edge, kind: f.kind, site: f.site,
    hero: f.hero,
    price: f.plans ? { of: "minecraft", src: f.plans.src, plans: f.plans.plans } : undefined,
    groups: Object.entries(rows).map(([label, rs]) => ({ label, rows: rs })),
    reasons: [
      { icon: "support", title: "One account for everything", body: (x) => `Game servers for ${x.games} games next to your VPS, websites, domains and email, on one bill.` },
      { icon: "backup", title: "Backups already on", body: (x) => `Every server keeps its last ${x.backupKeep} daily backups at no extra cost.` },
      { icon: "shield", title: "Prices you can check", body: "Every Nxeon price on this page is read live from checkout, and every one of theirs links to where we found it." },
    ],
    chooseNxeon: [
      (x) => `Your players are near ${x.regions.list}`,
      "You want your game server, website and domain in one account",
      (x) => (x.freeMc ? "You want to try a free Minecraft server first" : "You want backups on by default"),
      "You want NVMe storage",
    ],
    chooseThem: f.chooseThem,
    faq: [
      ...(f.plans ? [{ q: `Is Nxeon cheaper than ${f.name} for Minecraft?`, a: (x: HostCtx) => {
        const m = f.plans!.plans.map((p) => ({ p, t: x.mc.find((t) => t.ram === p.ram) })).filter((z) => z.t);
        if (!m.length) return `We don't sell the same RAM sizes, so compare the plan you need: Nxeon Minecraft starts at ${cheapestMc(x)}/mo.`;
        return `It depends on the size. ${m.map(({ p, t }) => `At ${p.ram} GB, Nxeon is ${$(t!.p)}/mo and ${f.name}'s ${p.name} is ${$(p.usd)}/mo`).join("; ")} (their prices as listed on their site, checked ${f.plans!.src.checked}).`;
      } }] : []),
      ...(f.refund ? [{ q: `Does ${f.name} offer refunds?`, a: (x: HostCtx) => `${f.name} states: ${f.refund!.text}. ${x.nonRefundable ? "Nxeon's Terms make fees non-refundable, and you can cancel anytime." : ""}` }] : []),
      ...(f.locations ? [{ q: "Where are the servers?", a: (x: HostCtx) => `${f.name} lists ${f.locations!.text}. Nxeon runs servers in ${x.regions.list}. Pick the one closest to your players.` }] : []),
      { q: "Can I run mods on Nxeon?", a: (x: HostCtx) => (x.oneClickMc ? "Yes. Minecraft servers get one-click mod installs from the NxLabs catalogue, plus full file access." : "Yes, with full file access to your server for mods and plugins.") },
      ...(f.extraFaq ?? []),
    ],
  };
