/**
 * Competitor facts for the comparisons the live site has no page for — ONE
 * constant per competitor, every figure with the competitor's own page it
 * came from and the date it was checked. Researched 2026-09-27 from each
 * host's own site only (pricing, features, locations, terms/refund pages);
 * prices re-read from the raw page HTML where the page renders them with JS.
 * A fact that couldn't be found on their own site is simply absent — never
 * filled in. Nxeon's side of every row comes from the system (./vs-hosts.ts).
 *
 * Re-check these before launch and whenever a competitor changes its
 * pricing; `checked` is shown on the page next to each figure.
 */

const CHECKED = "2026-09-27";
const S = (url: string): Src => ({ url, checked: CHECKED });
const $ = (n: number) => `$${n.toFixed(2)}`;

// ── the facts ───────────────────────────────────────────────────────────────
type Fact = { text: string; src: Src };
type GameFacts = {
  key: string; name: string; short?: string; board?: string;
  color: string; gain: string; type: string; edge: string; kind: string;
  site: Src;
  /** games they say they host */ games?: { n: number; text: string; src: Src };
  /** Minecraft Java plans, monthly USD as listed */ plans?: { src: Src; plans: HostPlan[] };
  /** number of locations they list */ locations?: { n: number; text: string; src: Src };
  refund?: Fact & { days: number };
  free?: Fact;
  slots?: Fact;
  storage?: Fact & { nvme: boolean };
  backups?: Fact & { paid?: boolean };
  ddos?: Fact;
  mods?: Fact & { oneClick: boolean };
  support?: Fact & { h24: boolean };
  panel?: Fact;
  yearly?: Fact & { pct: number };
  hero: { lead: string; highlight: string; body: (x: HostCtx) => string };
  chooseThem: string[];
  extraRows?: HostRow[];
  extraFaq?: { q: string; a: string }[];
};

